import{_ as s,o as e,c as i,a2 as n}from"./chunks/framework.BsAvorgW.js";const k=JSON.parse('{"title":"首次配置","description":"","frontmatter":{},"headers":[],"relativePath":"guide/first-setup.md","filePath":"guide/first-setup.md","lastUpdated":1784136889000}'),t={name:"guide/first-setup.md"};function l(r,a,o,p,h,d){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="首次配置" tabindex="-1">首次配置 <a class="header-anchor" href="#首次配置" aria-label="Permalink to &quot;首次配置&quot;">​</a></h1><h2 id="_1-获取-webui-token" tabindex="-1">1. 获取 WebUI Token <a class="header-anchor" href="#_1-获取-webui-token" aria-label="Permalink to &quot;1. 获取 WebUI Token&quot;">​</a></h2><p>Token 只用于首次初始化管理员账号，可以从启动日志取得。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Docker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> selena-proxy</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux systemd</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> selena-proxy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Windows 直接查看正在运行 SelenaProxy 的 PowerShell 窗口。</p><h2 id="_2-创建管理员" tabindex="-1">2. 创建管理员 <a class="header-anchor" href="#_2-创建管理员" aria-label="Permalink to &quot;2. 创建管理员&quot;">​</a></h2><p>打开 <code>http://服务器IP:17892</code>，输入日志中的 WebUI Token。验证通过后设置管理员账号和强密码。</p><p>密码需要：</p><ul><li>至少 8 位；</li><li>包含大写字母；</li><li>包含数字；</li><li>包含特殊符号，例如 <code>@</code>。</li></ul><h2 id="_3-填写供应商-api" tabindex="-1">3. 填写供应商 API <a class="header-anchor" href="#_3-填写供应商-api" aria-label="Permalink to &quot;3. 填写供应商 API&quot;">​</a></h2><p>登录<a href="https://www.dmdaili.com/" target="_blank" rel="noreferrer">多米代理</a>，创建代理提取链接。进入 SelenaProxy 的 <strong>设置</strong> 页面，将完整链接填入“多米 API 地址”。</p><p>如果原链接带有 <code>getnum</code>，SelenaProxy 会根据“单次提取数量”自动替换，不需要手动修改链接。</p><h2 id="_4-设置访问范围" tabindex="-1">4. 设置访问范围 <a class="header-anchor" href="#_4-设置访问范围" aria-label="Permalink to &quot;4. 设置访问范围&quot;">​</a></h2><p>至少确认以下内容：</p><ol><li><strong>对外访问地址</strong>：填写调用方可以访问到的服务器 IP 或域名，不带协议和端口。</li><li><strong>允许端口</strong>：HTTPS 接口通常使用 <code>443</code>。</li><li><strong>允许域名</strong>：每行一个，支持 <code>*.example.com</code> 形式的子域名通配。</li><li>点击页面底部的 <strong>保存配置</strong>。</li></ol><h2 id="_5-创建代理账号" tabindex="-1">5. 创建代理账号 <a class="header-anchor" href="#_5-创建代理账号" aria-label="Permalink to &quot;5. 创建代理账号&quot;">​</a></h2><p>进入 <strong>账号</strong> 页面，添加名称、代理用户名和代理密码。保存后前往 <strong>链接</strong> 页面复制地址。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>没有任何启用账号时，代理入口会返回 <code>407</code>，不会自动开放匿名访问。</p></div>`,18)])])}const u=s(t,[["render",l]]);export{k as __pageData,u as default};
